  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id            String    @id @default(uuid()) @map(\"userId\")\n  name          String?   @db.VarChar(255)\n  email         String    @unique\n  emailVerified DateTime?\n  image         String?   @db.VarChar(255)\n  phone         String?   @db.VarChar(20)\n  birthDate     DateTime?\n  password      String    @db.VarChar(255)\n  addressLine1  String?   @db.VarChar(255)\n  addressLine2  String?   @db.VarChar(255)\n  city          String?   @db.VarChar(100)\n  state         String?   @db.VarChar(100)\n  zipCode       String?   @db.VarChar(20)\n  country       String?   @db.VarChar(100)\n\n  // Multi-company ownership\n  ownedCompanies Company[] @relation(\"CompanyOwner\")\n\n  // All companies the user is linked to\n  companies Company[] @relation(\"CompanyUsers\")\n\n  // Active company context\n  companyId String?\n  company   Company? @relation(\"UserActiveCompany\", fields: [companyId], references: [id], onDelete: SetNull) // Clear active company if company is deleted\n\n  isActive        Boolean           @default(true)\n  role            Role              @default(CUSTOMER)\n  lastLogin       DateTime?\n  createdAt       DateTime          @default(now())\n  updatedAt       DateTime          @updatedAt\n  deletedAt       DateTime? // Added for soft deletes\n  ProjectCustomer ProjectCustomer[]\n  ProjectStaff    ProjectStaff[]\n  Project         Project[]\n\n  @@map(\"users\")\n}\n\nmodel Company {\n  id             String           @id @default(uuid()) @map(\"companyId\")\n  name           String           @unique @db.VarChar(255)\n  slogan         String?          @db.VarChar(255)\n  category       CompanyCategory?\n  type           BusinessType?\n  logo           String?          @db.VarChar(255)\n  domain         String?          @unique @db.VarChar(255)\n  subdomain      String?          @unique @db.VarChar(255)\n  isCustomDomain Boolean?         @default(false)\n  phone          String?          @db.VarChar(20)\n  supportEmail   String?          @unique @db.VarChar(255)\n  salesEmail     String?          @unique @db.VarChar(255)\n  addressLine1   String?          @db.VarChar(255)\n  addressLine2   String?          @db.VarChar(255)\n  city           String?          @db.VarChar(100)\n  state          String?          @db.VarChar(100)\n  zipCode        String?          @db.VarChar(20)\n  country        String?          @db.VarChar(100)\n\n  isActive           Boolean @default(true)\n  gmailConnected     Boolean @default(false)\n  office365Connected Boolean @default(false)\n\n  // Owner relation\n  ownerId String\n  owner   User   @relation(\"CompanyOwner\", fields: [ownerId], references: [id], onDelete: NoAction) // Prevent owner deletion to maintain company ownership\n\n  // Active users (reverse relation of `User.company`)\n  activeUsers User[] @relation(\"UserActiveCompany\")\n\n  // All users linked to this company\n  users User[] @relation(\"CompanyUsers\")\n\n  subscriptionPlanId String\n  subscriptionPlan   SubscriptionPlan @relation(fields: [subscriptionPlanId], references: [id], onDelete: NoAction) // Prevent plan deletion if companies exist\n\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime? // Added for soft deletes\n  Project   Project[]\n\n  @@map(\"companies\")\n}\n\nmodel SubscriptionPlan {\n  id             String       @id @default(uuid()) @map(\"planId\")\n  key            String       @unique @db.VarChar(50)\n  name           String       @unique @db.VarChar(100)\n  description    String?      @db.VarChar(500)\n  pricePerMonth  Decimal      @default(0.0)\n  billingCycle   BillingCycle\n  maxUsers       Int          @default(1)\n  maxAdmins      Int          @default(1)\n  maxManagers    Int          @default(0)\n  maxCustomers   Int          @default(10)\n  storageLimitMB Int          @default(100)\n  maxProjects    Int          @default(3)\n  features       Feature[]    @relation(\"PlanFeatures\")\n  companies      Company[]\n  isActive       Boolean      @default(true)\n  createdAt      DateTime     @default(now())\n  updatedAt      DateTime     @updatedAt\n  deletedAt      DateTime? // soft delete\n\n  @@map(\"subscription_plans\")\n}\n\nmodel Feature {\n  id        String             @id @default(uuid()) @map(\"featureId\")\n  key       String             @unique @db.VarChar(100)\n  label     String             @db.VarChar(100)\n  plans     SubscriptionPlan[] @relation(\"PlanFeatures\")\n  isActive  Boolean            @default(true)\n  createdAt DateTime           @default(now())\n  updatedAt DateTime           @updatedAt\n  deletedAt DateTime? // Added for soft deletes\n\n  @@map(\"features\")\n}\n\nmodel Project {\n  id          String        @id @default(uuid())\n  name        String        @db.VarChar(255)\n  description String?       @db.Text\n  status      ProjectStatus @default(PLANNING)\n  startDate   DateTime?\n  endDate     DateTime?\n\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade) // Delete projects if company is deleted\n  budget    Decimal?\n  progress  Int?\n  managerId String?\n  manager   User?    @relation(fields: [managerId], references: [id], onDelete: SetNull) // Allow projects to persist without a manager\n\n  customerid String?\n  customer   ProjectCustomer? @relation(\"ProjectToCustomer\")\n\n  staff     ProjectStaff[]\n  isActive  Boolean        @default(false)\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n  deletedAt DateTime? // Added for soft deletes\n\n  @@map(\"projects\")\n}\n\nmodel ProjectStaff {\n  id        String @id @default(uuid()) @map(\"projectStaffId\")\n  projectId String\n  userId    String\n\n  project Project @relation(fields: [projectId], references: [id], onDelete: Cascade) // Delete staff assignments if project is deleted\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade) // Delete staff assignments if user is deleted\n\n  assignedAt DateTime @default(now())\n\n  @@unique([projectId, userId])\n  @@map(\"project_staff\")\n}\n\nmodel ProjectCustomer {\n  id        String @id @default(uuid()) @map(\"projectCustomerId\")\n  projectId String @unique\n  userId    String\n\n  project Project @relation(\"ProjectToCustomer\", fields: [projectId], references: [id], onDelete: Cascade) // Delete customer assignment if project is deleted\n  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade) // Delete customer assignment if user is deleted\n\n  role    String?  @db.VarChar(100)\n  notes   String?  @db.Text\n  addedAt DateTime @default(now())\n\n  @@unique([projectId, userId])\n  @@map(\"project_customers\")\n}\n\nenum Role {\n  SUPER_ADMIN\n  ADMIN\n  MANAGER\n  STAFF\n  CUSTOMER\n  GUEST\n}\n\nenum CompanyCategory {\n  AGRICULTURE\n  AUTOMOTIVE\n  CONSTRUCTION\n  CONSULTING\n  EDUCATION\n  ENERGY\n  ENTERTAINMENT\n  FINANCE\n  FOOD_AND_BEVERAGE\n  GOVERNMENT\n  HEALTHCARE\n  HOSPITALITY\n  INTERIOR_DESIGN\n  MANUFACTURING\n  MARKETING\n  NON_PROFIT\n  PHARMACEUTICAL\n  REAL_ESTATE\n  RETAIL\n  TECHNOLOGY\n  TELECOMMUNICATIONS\n  TRANSPORTATION\n}\n\nenum BusinessType {\n  SERVICES\n  PRODUCTS\n  SERVICES_AND_PRODUCTS\n  OTHER\n}\n\nenum BillingCycle {\n  ONE_TIME\n  NET_7\n  NET_15\n  MONTHLY\n  QUARTERLY\n  ANNUALLY\n}\n\nenum ProjectStatus {\n  PLANNING\n  IN_PROGRESS\n  ON_HOLD\n  COMPLETED\n  CANCELED\n  ARCHIVED\n}\n",
